@extends('layouts.app') @section('title','Моя практика') @section('content')<style>.practice-action{min-height:52px}.progress{height:22px}</style><h1 class="h4">🏭 Моя практика</h1>@if(!$active)<div class="alert alert-secondary">Практика пока не назначена.</div>@else<div class="card mb-3"><div class="card-body"><div class="d-flex justify-content-between"><div><b>{{$active->practice_type}}</b><div>{{$active->organization_name}}</div><small>{{$active->starts_on}} — {{$active->ends_on}}</small></div><span class="badge text-bg-primary h-100">{{$active->status}}</span></div>@if($progress['planned'])<div class="mt-3">Подтверждено {{$progress['hours']}} из {{$progress['planned']}} ч.</div><div class="progress"><div class="progress-bar" style="width:{{$progress['percent']}}%">{{$progress['percent']}}%</div></div>@endif<div class="small mt-2">Записей: {{$progress['total']}} · подтверждено: {{$progress['confirmed']}} · ожидают: {{$progress['pending']}}</div></div></div>@foreach($notifications as $n)<div class="alert alert-warning"><b>{{$n->title}}</b><div>{{$n->message}}</div><form method="post" action="{{route('practice-student.notification.read',$n->id)}}">@csrf<button class="btn btn-sm btn-outline-dark mt-1">Прочитано</button></form></div>@endforeach<div class="card mb-3"><div class="card-body"><h2 class="h6">✍️ Запись в дневник</h2><form method="post" id="diaryForm" action="{{route('practice-student.diary',$active->id)}}">@csrf<div class="row g-2"><div class="col-md-3"><input type="date" name="work_date" value="{{date('Y-m-d')}}" class="form-control form-control-lg" required></div><div class="col-md-2"><input type="number" step=".25" name="hours" class="form-control form-control-lg" placeholder="Часы" required></div><div class="col-md-7"><textarea name="work_description" class="form-control" rows="3" required placeholder="Что выполнял сегодня"></textarea></div></div><input type="hidden" name="latitude" id="lat"><input type="hidden" name="longitude" id="lon"><input type="hidden" name="location_accuracy" id="acc"><div class="d-grid gap-2 d-md-flex mt-2"><button type="button" id="geo" class="btn btn-outline-secondary practice-action">📍 Добавить геометку</button><button class="btn btn-primary practice-action flex-grow-1">Отправить запись</button></div><small id="geoStatus" class="text-secondary"></small></form></div></div><div class="card mb-3"><div class="card-body"><h2 class="h6">📷 Фотоотчёт</h2><form method="post" enctype="multipart/form-data" action="{{route('practice-student.photo',$active->id)}}" class="row g-2">@csrf<div class="col-md-4"><input type="file" name="photo" accept="image/*" capture="environment" class="form-control" required></div><div class="col-md-3"><input type="date" name="work_date" value="{{date('Y-m-d')}}" class="form-control"></div><div class="col-md-4"><input name="caption" class="form-control" placeholder="Что на фото"></div><div class="col"><button class="btn btn-outline-primary w-100">Загрузить</button></div></form></div></div><div class="card mb-3"><div class="card-body"><h2 class="h6">📝 Итоговый отчёт</h2><form method="post" action="{{route('practice-student.report',$active->id)}}">@csrf<textarea name="student_report" rows="6" class="form-control" placeholder="Итоговый отчёт">{{$active->student_report}}</textarea><button class="btn btn-success w-100 practice-action mt-2">Отправить отчёт</button></form></div></div><h2 class="h6">Дневник</h2>@foreach($diary as $d)<div class="card mb-2"><div class="card-body py-2"><b>{{$d->work_date}} · {{$d->hours}} ч.</b><span class="badge {{$d->partner_status==='confirmed'?'text-bg-success':($d->partner_status==='rejected'?'text-bg-danger':'text-bg-warning')}}">@if($d->partner_status==='confirmed') подтверждено @elseif($d->partner_status==='rejected') возвращено @else ожидает @endif</span><div>{{$d->work_description}}</div>@if($d->partner_comment)<small class="text-danger">{{$d->partner_comment}}</small>@endif @if($d->latitude)<small class="text-secondary d-block">📍 Геометка приложена студентом</small>@endif</div></div>@endforeach<script>document.getElementById('geo').onclick=()=>{let s=document.getElementById('geoStatus');if(!navigator.geolocation){s.textContent='Геолокация не поддерживается';return}s.textContent='Запрашиваю местоположение…';navigator.geolocation.getCurrentPosition(p=>{lat.value=p.coords.latitude;lon.value=p.coords.longitude;acc.value=p.coords.accuracy;s.textContent='✓ Геометка добавлена (точность около '+Math.round(p.coords.accuracy)+' м)'},()=>s.textContent='Геометка не добавлена. Запись можно отправить без неё.',{enableHighAccuracy:true,timeout:10000,maximumAge:0})};</script>@endif @endsection